// Owner question set 2 (V1.15), part G: SQL revenue exercise, testing, CI/CD and build (CI/CD shared with DevOps).
import { kp, Q } from './kp.js';

const DB = 'Databases & SQL', TS = 'Testing', CI = 'DevOps & CI/CD', BT = 'Build Tools';
const src = { source: 'owner-set2' };
const sh = { source: 'owner-set2', cat: 'shared', roles: ['java-backend', 'devops'] };

export const V115_G = [
  // ---------------------------------------------------------------- 19. SQL exercise: customer revenue by year
  Q('nq-256', DB, 'M', 'scenario', 'Given Customer and Orders tables, write a query to calculate total revenue per customer per year.',
    [kp('Join customers and orders on customer_id', 'join', 'customer_id'), kp('Extract year from order_date', 'year', 'extract', 'year('), kp('SUM(amount) as revenue', 'sum', 'revenue'), kp('GROUP BY customer and year', 'group by'), kp('ORDER BY customer name, year', 'order by')],
    'SELECT c.customer_id, c.name, EXTRACT(YEAR FROM o.order_date) AS order_year, SUM(o.amount) AS total_revenue FROM customer c JOIN orders o ON o.customer_id = c.customer_id GROUP BY c.customer_id, c.name, EXTRACT(YEAR FROM o.order_date) ORDER BY c.name, order_year; The join links each order to its customer, EXTRACT, or YEAR() in MySQL and SQL Server, gets the year, SUM adds the order amounts, and GROUP BY produces one row per customer per year. I include customer_id in the grouping so two customers with the same name are not merged. If revenue is quantity times price in an order_items table, I would join that too and sum quantity times unit price, and filter out cancelled orders.',
    'How would you include customers with no orders as zero revenue?', src),
  Q('nq-257', DB, 'E', 'scenario', 'How would you join the Customer and Orders tables?',
    [kp('JOIN ... ON orders.customer_id = customer.customer_id', 'join', 'on', 'customer_id'), kp('Table aliases for readability', 'alias*', 'c.', 'o.'), kp('Foreign key relationship one customer to many orders', 'foreign key', 'one to many', 'one-to-many'), kp('Choose INNER or LEFT depending on requirement', 'inner', 'left')],
    'Orders has a foreign key customer_id that references the primary key of Customer, a one-to-many relationship. So: FROM customer c JOIN orders o ON o.customer_id = c.customer_id. Aliases keep it readable. An inner join returns only customers who have orders, which is what a revenue report usually wants; a LEFT JOIN from customer keeps customers without orders, with NULLs for order columns. An index on orders.customer_id makes the join efficient.',
    'What happens if you forget the ON condition?', src),
  Q('nq-258', DB, 'E', 'concept', 'Which columns would you use to join the tables, and why use customer_id?',
    [kp('customer_id: primary key in Customer, foreign key in Orders', 'primary key', 'foreign key', 'customer_id'), kp('Unique and stable identifier; names are not unique and can change', 'unique', 'stable', 'name*', 'change'), kp('Indexed for fast joins', 'index*', 'fast')],
    'I join on customer_id because it is the primary key of Customer and the foreign key in Orders: it uniquely identifies a customer and never changes. Joining on the name would be wrong: two customers can share a name, names have typos and can change, so orders would be attributed to the wrong person or lost. Keys are also compact and indexed, so the join is efficient. The relationship is defined by the foreign key constraint, so the join follows the data model.',
    'Why would you also group by customer_id even if you display only the name?', src),
  Q('nq-259', DB, 'E', 'concept', 'Which join is appropriate for retrieving matching customer and order records?',
    [kp('INNER JOIN returns only matching rows', 'inner join', 'matching'), kp('Revenue per customer per year needs only customers with orders', 'only customers with orders', 'with orders', 'no revenue'), kp('LEFT JOIN if customers without orders must appear', 'left join', 'without orders', 'zero')],
    'An INNER JOIN, because it returns only rows where a customer has a matching order, which is exactly what is needed to compute revenue from orders: customers without orders contribute no revenue and do not appear. If the business wants every customer listed, including those with zero revenue, I would use customer LEFT JOIN orders and COALESCE(SUM(o.amount), 0), noting that the year then has to come from a separate calendar or year list for customers without orders.',
    'How would the WHERE clause behave differently with a LEFT JOIN?', src),
  Q('nq-260', DB, 'E', 'concept', 'What is the difference between INNER JOIN and LEFT JOIN?',
    [kp('INNER: only rows with matches in both tables', 'inner', 'both', 'match*'), kp('LEFT: all rows from the left table, NULLs where no match', 'left', 'all rows', 'null*'), kp('Example: customers without orders', 'example', 'without orders', 'never ordered'), kp('Filtering right table in WHERE turns LEFT into INNER', 'where', 'on clause', 'turns', 'filter')],
    'INNER JOIN returns only the rows that have a match in both tables: customers who have at least one order, one row per matching pair. LEFT JOIN, or LEFT OUTER JOIN, returns every row from the left table, and the matching rows from the right; where there is no match, the right columns are NULL. So customer LEFT JOIN orders also lists customers who never ordered. A classic mistake: putting a condition on the right table, like o.status = PAID, in the WHERE clause removes the NULL rows and effectively turns it back into an inner join; such conditions belong in the ON clause.',
    'How would you find customers who have never placed an order?', src),
  Q('nq-261', DB, 'E', 'concept', 'How would you extract the year from an order date?',
    [kp('EXTRACT(YEAR FROM order_date) (standard, Oracle, PostgreSQL)', 'extract', 'year from'), kp('YEAR(order_date) in MySQL/SQL Server; DATE_PART/strftime/TO_CHAR', 'year(', 'date_part', 'to_char', 'strftime'), kp('Function on column can prevent index use; use date ranges in WHERE', 'index', 'sargab*', 'range', 'between')],
    'Standard SQL, Oracle and PostgreSQL use EXTRACT(YEAR FROM o.order_date); MySQL and SQL Server offer YEAR(o.order_date); PostgreSQL also has DATE_PART(\'year\', order_date) and Oracle TO_CHAR(order_date, \'YYYY\'), which returns text. In the SELECT and GROUP BY that is fine. But in a WHERE clause, wrapping the column in a function usually prevents using an index on order_date, so to filter a year I would write order_date >= DATE \'2024-01-01\' AND order_date < DATE \'2025-01-01\' instead.',
    'Why is WHERE YEAR(order_date) = 2024 potentially slow?', src),
  Q('nq-262', DB, 'E', 'concept', 'How would you calculate total revenue using an aggregate function?',
    [kp('SUM(amount) over the grouped rows', 'sum'), kp('Use with GROUP BY for per-group totals', 'group by'), kp('NULL handling with COALESCE; exclude cancelled/refunded', 'coalesce', 'null', 'cancel*', 'refund*'), kp('Line items: SUM(quantity * unit_price); numeric types for money', 'quantity', 'unit_price', 'decimal', 'numeric')],
    'Use SUM over the amount column: SUM(o.amount) AS total_revenue, combined with GROUP BY to get one total per group. SUM ignores NULLs, and COALESCE(SUM(o.amount), 0) returns zero instead of NULL when a group has no values, for example with a LEFT JOIN. If revenue must be computed from line items, use SUM(oi.quantity * oi.unit_price), and apply business rules such as excluding cancelled or refunded orders with a WHERE condition on status. Money columns should be DECIMAL or NUMERIC, not floating point, to avoid rounding errors.',
    'What other aggregate functions would be useful in this report?', src),
  Q('nq-263', DB, 'E', 'concept', 'How would you group the results by customer name and order year?',
    [kp('GROUP BY customer columns and the year expression', 'group by', 'year'), kp('All non-aggregated SELECT columns must be in GROUP BY', 'non aggregated', 'non-aggregated', 'all columns', 'not inside an aggregate', 'every column'), kp('Include customer_id to avoid merging same names', 'customer_id', 'same name'), kp('Some databases allow alias or position in GROUP BY', 'alias', 'position')],
    'GROUP BY c.customer_id, c.name, EXTRACT(YEAR FROM o.order_date). Every column in the SELECT that is not inside an aggregate must appear in the GROUP BY, so the database knows how to form groups: here one group per customer and year, and SUM is computed inside each group. Grouping by customer_id as well as name prevents two different customers with the same name from being merged into one row. PostgreSQL and MySQL also accept the select alias, like GROUP BY order_year, or column positions, but repeating the expression is the most portable.',
    'What error do you get if a selected column is missing from GROUP BY?', src),
  Q('nq-264', DB, 'E', 'concept', 'Why is GROUP BY required for this aggregation?',
    [kp('Without GROUP BY, SUM collapses all rows into one total', 'one total', 'single row', 'all rows', 'single number'), kp('GROUP BY creates one group per customer per year', 'one group', 'per customer', 'per year'), kp('Mixing aggregated and non-aggregated columns needs GROUP BY', 'non aggregated', 'non-aggregated', 'error')],
    'An aggregate like SUM collapses rows. Without GROUP BY, SUM(o.amount) over the whole join returns a single number, the total revenue of all customers in all years. We need the total per customer per year, so GROUP BY tells the database to split the rows into groups with the same customer and year and compute the SUM separately for each group, returning one row per group. Also, selecting customer name next to an aggregate without grouping is an error in standard SQL, because the database would not know which name to show.',
    'How would you keep only customers with more than 10,000 revenue in a year?', src),
  Q('nq-265', DB, 'E', 'concept', 'How would you sort the output by customer name and year?',
    [kp('ORDER BY name, year ascending', 'order by'), kp('ORDER BY can use the select alias', 'alias', 'aliases'), kp('DESC for most recent first or highest revenue', 'desc'), kp('Sorting happens last, after grouping', 'last', 'after group*')],
    'Add ORDER BY c.name, order_year at the end. It sorts by customer name first and, within the same name, by year, both ascending by default; you can write DESC for the most recent year first, or ORDER BY total_revenue DESC for the top customers. Unlike GROUP BY, ORDER BY may use the select aliases, because it is evaluated last, after grouping and aggregation. Without ORDER BY the row order is not guaranteed at all.',
    'In what logical order does SQL evaluate FROM, WHERE, GROUP BY, HAVING, SELECT and ORDER BY?', src),
  Q('nq-266', DB, 'E', 'concept', 'What is the difference between GROUP BY and ORDER BY?',
    [kp('GROUP BY forms groups for aggregation, reducing rows', 'groups', 'aggregat*', 'reduc*'), kp('ORDER BY only sorts the final result, row count unchanged', 'sort*', 'order', 'unchanged'), kp('HAVING filters groups', 'having'), kp('GROUP BY does not guarantee order', 'not guarantee', 'no order')],
    'GROUP BY combines rows that share the same values in the listed columns into a single group, so aggregates like SUM or COUNT can be computed per group; it reduces the number of rows, and HAVING can filter the groups. ORDER BY just sorts the final result rows by the given columns or expressions, ascending or descending; it does not change how many rows there are. GROUP BY does not guarantee any output order, so if you want sorted groups you still need ORDER BY.',
    'What is the difference between WHERE and HAVING?', src),
  Q('nq-267', DB, 'M', 'scenario', 'How would you handle multiple orders from the same customer in the same year and return one row per customer per year?',
    [kp('GROUP BY customer and year aggregates multiple orders into one row', 'group by', 'one row', 'aggregat*'), kp('SUM amounts, COUNT orders', 'sum', 'count'), kp('Avoid duplicates from extra joins (line items) inflating sums', 'duplicat*', 'inflat*', 'fan out', 'line item*'), kp('Use DISTINCT carefully or pre-aggregate in a subquery/CTE', 'subquery', 'cte', 'pre aggregat*', 'distinct')],
    'That is exactly what grouping does: all orders of customer 7 in 2024 fall into the same group, SUM adds their amounts and COUNT(o.order_id) can show how many orders there were, so the result has one row per customer per year. A subtle trap is joining additional one-to-many tables, such as order_items or payments: each order is then repeated per item, which inflates SUM(o.amount). In that case I pre-aggregate in a subquery or CTE, for example sum items per order first, then join and group by customer and year, rather than patching with DISTINCT.',
    'Can you write the CTE version that avoids double counting?', src),

  // ---------------------------------------------------------------- 20. Testing
  Q('nq-268', TS, 'E', 'concept', 'What is unit testing?',
    [kp('Testing the smallest unit (method/class) in isolation', 'smallest', 'isolation', 'single class', 'method'), kp('Dependencies replaced with mocks/stubs', 'mock*', 'stub*'), kp('Fast, automated, repeatable; run on every build', 'fast', 'automated', 'repeatable', 'every build'), kp('Arrange-Act-Assert; cover edge cases', 'arrange', 'given when then', 'edge case*'), kp('Tools: JUnit 5, Mockito, AssertJ', 'junit', 'mockito', 'assertj')],
    'A unit test checks the smallest testable piece of code, usually one class or method, in isolation from its dependencies: databases, HTTP clients and other services are replaced with mocks or stubs. Unit tests are fast, run in milliseconds, automated and deterministic, so they run on every build and give quick feedback, document behaviour and make refactoring safe. A good test follows Arrange-Act-Assert, or Given-When-Then, checks one behaviour, and covers normal, boundary and error cases. In Java we use JUnit 5 with Mockito and AssertJ.',
    'What makes a unit test flaky?', src),
  Q('nq-269', TS, 'E', 'concept', 'What is integration testing?',
    [kp('Tests that several components work together with real infrastructure', 'together', 'components', 'real'), kp('Examples: repository against a real DB, REST endpoint through Spring context', 'database', 'repository', 'endpoint', 'spring context'), kp('Tools: @SpringBootTest, Testcontainers, WireMock, MockMvc', 'springboottest', 'testcontainers', 'wiremock', 'mockmvc'), kp('Slower, fewer than unit tests (test pyramid)', 'slower', 'pyramid', 'fewer')],
    'Integration tests check that several parts work correctly together, including real infrastructure or the framework: a repository with its queries against a real PostgreSQL, a REST controller through the full Spring context with serialisation, validation and security, or a Kafka consumer reading real messages. In Spring Boot you use @SpringBootTest or slice tests like @DataJpaTest and @WebMvcTest, Testcontainers to start real databases and brokers in Docker, and WireMock to simulate external HTTP APIs. They catch wiring, mapping, SQL and configuration bugs that unit tests miss, but they are slower, so you have fewer of them, following the test pyramid.',
    'Why is Testcontainers preferred over H2 for database tests?', src),
  Q('nq-270', TS, 'E', 'concept', 'What is the difference between unit testing and integration testing?',
    [kp('Scope: one unit in isolation vs multiple components together', 'isolation', 'together', 'scope'), kp('Dependencies mocked vs real (DB, broker, Spring context)', 'mock*', 'real'), kp('Speed and number: many fast unit vs fewer slower integration', 'fast', 'slow*', 'many', 'fewer'), kp('Bugs found: logic vs wiring/config/contracts', 'logic', 'wiring', 'configuration', 'contract*')],
    'A unit test checks one class in isolation, mocking its dependencies; it is very fast, pinpoints the failing logic and you write many of them. An integration test checks that components work together with real collaborators, such as the Spring context, the database, message broker or HTTP layer; it is slower and more complex to set up, but finds problems unit tests cannot, like wrong SQL, misconfigured beans, JSON mapping or transaction boundaries. A healthy suite follows the test pyramid: many unit tests, fewer integration tests, and a few end-to-end tests.',
    'What is the test pyramid, and what is the "ice cream cone" anti-pattern?', { ...src, sameAs: 'jb-261' }),
  Q('nq-271', TS, 'E', 'scenario', 'Which testing frameworks have you used?',
    [kp('JUnit 5 for unit tests', 'junit'), kp('Mockito for mocking, AssertJ/Hamcrest assertions', 'mockito', 'assertj', 'hamcrest'), kp('Spring Boot Test: MockMvc, @SpringBootTest, slices', 'mockmvc', 'springboottest', 'webmvctest', 'datajpatest'), kp('Testcontainers, WireMock, REST Assured', 'testcontainers', 'wiremock', 'rest assured'), kp('Performance/contract tools: JMeter, Gatling, Pact, Spring Cloud Contract', 'jmeter', 'gatling', 'pact', 'contract')],
    'Answer with what you actually used and how. For example: JUnit 5 for all unit tests, using parameterised tests and nested classes; Mockito for mocking dependencies and verifying interactions; AssertJ for fluent assertions; Spring Boot Test with @WebMvcTest and MockMvc for controllers, @DataJpaTest for repositories and @SpringBootTest for full integration tests; Testcontainers to run PostgreSQL and Kafka in Docker during tests; WireMock to stub external APIs; REST Assured for API tests; Pact or Spring Cloud Contract for consumer-driven contracts; JMeter or Gatling for load tests; and JaCoCo with SonarQube for coverage in the pipeline.',
    'How do you decide what to test at which level?', src),
  Q('nq-272', TS, 'E', 'concept', 'What is JUnit 5?',
    [kp('Current JUnit: Platform, Jupiter, Vintage', 'platform', 'jupiter', 'vintage'), kp('Annotations @Test, @BeforeEach, @AfterEach, @DisplayName, @Nested', '@test', '@beforeeach', '@displayname', '@nested'), kp('Parameterized tests, assertThrows, assertAll', 'parameterized', 'assertthrows', 'assertall'), kp('Extension model (@ExtendWith) replacing runners', 'extendwith', 'extension*', 'runner*')],
    'JUnit 5 is the current generation of the standard Java testing framework, made of three parts: the JUnit Platform, which launches tests and integrates with IDEs and build tools; JUnit Jupiter, the new programming and extension model; and JUnit Vintage, to run old JUnit 4 tests. It uses annotations like @Test, @BeforeEach, @AfterEach, @BeforeAll, @DisplayName, @Nested and @Disabled; supports @ParameterizedTest with sources like @ValueSource and @CsvSource; offers assertions such as assertEquals, assertThrows and assertAll; and replaces JUnit 4 runners and rules with a single extension model, @ExtendWith, used by Mockito and Spring.',
    'How do you write a parameterized test in JUnit 5?', src),
  Q('nq-273', TS, 'E', 'concept', 'What is Mockito, and why is it used?',
    [kp('Mocking framework creating test doubles', 'mocking', 'test double*', 'mock*'), kp('Isolate class under test from dependencies', 'isolat*', 'dependenc*'), kp('Stub with when().thenReturn(), verify interactions', 'when', 'thenreturn', 'verify'), kp('@Mock, @InjectMocks, MockitoExtension', '@mock', '@injectmocks', 'mockitoextension'), kp('Argument matchers and captors', 'argumentcaptor', 'any(', 'matcher*')],
    'Mockito is the most popular Java mocking framework. It creates mock objects that stand in for a class dependencies, such as repositories, HTTP clients or other services, so you can test the class in isolation, quickly, and simulate situations that are hard to produce for real, like timeouts or errors. You stub behaviour with when(repo.findById(1L)).thenReturn(Optional.of(user)) or thenThrow, and check interactions with verify(emailSender).send(any()). With JUnit 5 you use @ExtendWith(MockitoExtension.class), @Mock for dependencies and @InjectMocks for the class under test, plus argument matchers and ArgumentCaptor to inspect what was passed.',
    'Why should you avoid mocking types you do not own?', src),
  Q('nq-274', TS, 'M', 'scenario', 'How do you mock external dependencies during unit testing?',
    [kp('Depend on interfaces and inject via constructor', 'interface*', 'constructor', 'inject*'), kp('Mockito mocks for repositories/clients; stub responses and errors', 'mockito', 'mock*', 'stub*', 'thenthrow'), kp('Verify calls and arguments', 'verify', 'argumentcaptor'), kp('@MockBean / @MockitoBean in Spring tests', '@mockbean', '@mockitobean'), kp('WireMock/Testcontainers for HTTP/DB at integration level', 'wiremock', 'testcontainers')],
    'I design classes so external dependencies come in through the constructor as interfaces: PaymentClient, OrderRepository, Clock. In a unit test I create Mockito mocks with @Mock, inject them with @InjectMocks or by calling the constructor, and stub what each should return: success, empty results, exceptions like a timeout, so every branch of my code is exercised. Then I assert the result and verify important interactions, for example that the payment client was called once with the right amount, using ArgumentCaptor. Time and randomness are injected too, a fixed Clock. In Spring slice tests @MockitoBean, formerly @MockBean, replaces a bean in the context. For the HTTP or database layer itself I prefer WireMock or Testcontainers in integration tests rather than mocks.',
    'What is the risk of over-mocking?', src),
  Q('nq-275', TS, 'M', 'concept', 'What is a mock object, and what is a spy in Mockito?',
    [kp('Mock: fake object, all methods return defaults unless stubbed', 'fake', 'default*', 'stubbed', 'null'), kp('Spy: wraps a real object, real methods called unless stubbed', 'spy', 'real object', 'real method*', 'partial'), kp('Use doReturn().when() with spies', 'doreturn'), kp('Spies for legacy code; prefer mocks', 'legacy', 'prefer', 'sparingly')],
    'A mock is a completely fake object created from a class or interface: every method does nothing and returns a default, null, zero, false or an empty collection, unless you stub it, and Mockito records calls so you can verify them. A spy wraps a real object: calls go to the real methods unless you stub specific ones, so it is a partial mock, useful for legacy code where you want real behaviour but need to override or observe one method. With spies, stub using doReturn(value).when(spy).method() to avoid calling the real method during stubbing. Spies are a smell in new code; usually a better design with injected dependencies avoids them.',
    'Why does when(spy.method()) sometimes cause problems?', src),
  Q('nq-276', TS, 'E', 'concept', 'What annotations and assertions do you commonly use in unit tests?',
    [kp('@Test, @BeforeEach/@AfterEach, @BeforeAll, @DisplayName, @ParameterizedTest, @Nested', '@test', '@beforeeach', '@parameterizedtest', '@displayname'), kp('Mockito: @ExtendWith(MockitoExtension), @Mock, @InjectMocks, @Captor', '@mock', '@injectmocks', '@captor', 'mockitoextension'), kp('Assertions: assertEquals, assertTrue/False, assertThrows, assertAll, assertNotNull', 'assertequals', 'asserttrue', 'assertthrows', 'assertall'), kp('AssertJ fluent assertThat', 'assertthat', 'assertj')],
    'JUnit 5 annotations: @Test, @BeforeEach and @AfterEach for setup and cleanup, @BeforeAll and @AfterAll for one-time setup, @DisplayName for readable names, @Nested to group scenarios, @ParameterizedTest with @CsvSource or @MethodSource, and @Disabled. Mockito: @ExtendWith(MockitoExtension.class), @Mock, @InjectMocks, @Captor and @Spy. Spring: @WebMvcTest, @DataJpaTest, @SpringBootTest, @MockitoBean. Assertions: assertEquals, assertNotNull, assertTrue and assertFalse, assertThrows to check exceptions, assertAll to group checks, and often AssertJ assertThat(result).isEqualTo(...), hasSize, extracting and containsExactly for readable messages.',
    'Why is assertAll useful?', src),
  Q('nq-277', TS, 'E', 'concept', 'What is the purpose of the @Test annotation?',
    [kp('Marks a method as a test case to be run by JUnit', 'marks', 'test method', 'test case'), kp('Test passes unless an assertion fails or exception thrown', 'passes', 'assertion fail*', 'exception'), kp('JUnit 5: org.junit.jupiter.api.Test, no expected/timeout attributes (use assertThrows/assertTimeout)', 'jupiter', 'assertthrows', 'asserttimeout', 'expected'), kp('Method should be non-private, void, no args', 'void', 'non private', 'public')],
    '@Test marks a method as a test case, so the JUnit engine discovers and runs it, reporting each one separately. The test passes if the method finishes normally, and fails if an assertion fails or an unexpected exception is thrown. In JUnit 5, from org.junit.jupiter.api.Test, test methods return void, must not be private, and the class does not need to be public. Unlike JUnit 4, it has no expected or timeout attributes: you use assertThrows and assertTimeout, or @Timeout, instead.',
    'How do you test that a method throws an exception in JUnit 5?', src),
  Q('nq-278', TS, 'E', 'concept', 'How do you use assertions such as assertTrue() and assertFalse()?',
    [kp('assertTrue(condition) passes when condition is true; assertFalse when false', 'asserttrue', 'assertfalse', 'condition'), kp('Optional failure message (lazy supplier)', 'message', 'supplier'), kp('Prefer specific assertions (assertEquals, AssertJ) for clearer failures', 'assertequals', 'specific', 'clearer', 'assertj'), kp('Example usage', 'isvalid', 'example', 'isempty')],
    'assertTrue(condition) passes if the boolean expression is true and fails otherwise; assertFalse is the opposite. For example assertTrue(validator.isValid(order)) and assertFalse(cart.isEmpty()). Both accept a failure message, or a Supplier<String> so the message is only built on failure: assertTrue(user.isActive(), () -> "user " + id + " should be active"). Because a failing assertTrue only reports expected true but was false, I prefer more specific assertions when possible, assertEquals(3, items.size()) or AssertJ assertThat(items).hasSize(3), which explain what went wrong.',
    'Why is assertEquals(expected, actual) argument order important?', src),
  Q('nq-279', TS, 'M', 'scenario', 'How would you test a service that interacts with multiple downstream systems?',
    [kp('Unit tests with each downstream client mocked, covering success and failure combinations', 'mock*', 'success', 'failure', 'combination*'), kp('Integration tests with WireMock/Testcontainers for real protocols', 'wiremock', 'testcontainers'), kp('Test timeouts, retries, circuit breakers, partial failures', 'timeout*', 'retr*', 'circuit breaker*', 'partial'), kp('Contract tests (Pact / Spring Cloud Contract)', 'contract test*', 'pact', 'spring cloud contract'), kp('Few end-to-end tests in a staging environment', 'end to end', 'end-to-end', 'staging')],
    'At unit level I mock each downstream client interface and test the orchestration logic: all succeed, each one fails, timeouts, empty or unexpected responses, and verify that compensations or fallbacks happen and calls are made in the right order with the right data. At integration level I run the service with WireMock stubbing the HTTP systems, including delays and 500 errors to exercise timeouts, retries and circuit breakers, and Testcontainers for its database and Kafka, asserting the persisted state and published messages. Consumer-driven contract tests with Pact or Spring Cloud Contract make sure my assumptions match each provider real API. Finally a small number of end-to-end tests run in a staging environment.',
    'How would you simulate a slow downstream service?', src),
  Q('nq-280', TS, 'M', 'scenario', 'How do you validate success and failure scenarios in integration tests?',
    [kp('Arrange real or stubbed dependencies for each scenario', 'stub*', 'wiremock', 'arrange'), kp('Assert HTTP status, response body and headers', 'status', 'response body', 'header*'), kp('Assert side effects: DB state, published messages, no partial writes', 'database', 'state', 'message*', 'side effect*', 'rollback'), kp('Failure cases: 4xx/5xx downstream, timeouts, invalid input, duplicates', 'timeout*', '5xx', '500', 'invalid', 'duplicate*'), kp('Isolated, repeatable data setup and cleanup', 'clean*', 'isolat*', 'repeatable', 'test data')],
    'For each scenario I set up the world explicitly: test data in the Testcontainers database, and WireMock stubs for downstream systems returning a success, a 500, a 404 or a delay longer than the timeout. Then I call the API through MockMvc, WebTestClient or REST Assured and assert the HTTP status, the response body and headers. I also assert the side effects, which is where integration bugs hide: the right rows were written, or for failures nothing partial was committed, the expected Kafka event was or was not published, retries happened the configured number of times, and errors were mapped to the agreed error format. Each test cleans up or uses unique data so tests are independent and repeatable.',
    'How would you assert that a Kafka event was published?', src),
  Q('nq-281', TS, 'M', 'concept', 'What is JMeter used for?',
    [kp('Apache JMeter: load and performance testing tool', 'load test*', 'performance test*', 'apache'), kp('Simulates many concurrent users with thread groups', 'thread group*', 'concurrent users', 'virtual users'), kp('Measures response time, throughput, error rate, percentiles', 'response time', 'throughput', 'error rate', 'percentile*'), kp('Supports HTTP, JDBC, JMS; CLI mode in CI', 'http', 'jdbc', 'non gui', 'cli', 'ci'), kp('Alternatives: Gatling, k6', 'gatling', 'k6')],
    'Apache JMeter is an open-source tool for load and performance testing. You build a test plan with thread groups that simulate many concurrent users, samplers for HTTP requests, JDBC queries or JMS messages, timers for think time, extractors to correlate values like tokens, and assertions on responses. It reports response times, throughput, error rates and percentiles such as p95 and p99, so you can find how many requests per second the API handles, where latency degrades and when errors start. For real tests you run it in non-GUI mode, often in CI or distributed across machines. Gatling and k6 are code-based alternatives.',
    'What is the difference between load, stress and soak tests?', src),
  Q('nq-282', TS, 'M', 'scenario', 'How do you test API integrations across multiple services?',
    [kp('Consumer-driven contract tests (Pact/Spring Cloud Contract)', 'contract', 'pact', 'spring cloud contract'), kp('Integration tests with WireMock stubs from contracts/OpenAPI', 'wiremock', 'openapi', 'stub*'), kp('End-to-end tests in a shared test environment for key flows', 'end to end', 'end-to-end', 'environment', 'key flow*'), kp('Test data management, correlation ids, observability', 'test data', 'correlation', 'tracing'), kp('Backward compatibility checks on schema changes', 'backward compat*', 'schema', 'version*')],
    'I use several layers. Consumer-driven contract tests, with Pact or Spring Cloud Contract, let each consumer publish the requests and responses it relies on, and the provider build verifies it still satisfies them, catching breaking changes before deployment. Within each service, integration tests use WireMock stubs, ideally generated from the OpenAPI spec or contracts, so they match reality. Schema changes for events are checked for backward compatibility in a schema registry. Then a small suite of end-to-end tests runs the critical journeys, like placing and paying an order, across deployed services in a test environment, with controlled test data and correlation ids so failures can be traced through logs and distributed tracing.',
    'Why are contract tests better than relying on end-to-end tests alone?', src),

  // ---------------------------------------------------------------- 21. CI/CD, build tools and deployment (shared with DevOps)
  Q('nq-283', CI, 'E', 'concept', 'What is CI/CD?',
    [kp('Continuous Integration: merge often, automated build and tests', 'continuous integration', 'merge', 'automated build', 'tests'), kp('Continuous Delivery/Deployment: automated release to environments', 'continuous delivery', 'continuous deployment', 'release', 'deploy*'), kp('Pipeline automates build, test, scan, package, deploy', 'pipeline', 'automat*'), kp('Benefits: fast feedback, fewer integration problems, reliable releases', 'feedback', 'reliable', 'faster', 'frequent')],
    'CI/CD is the practice of automating how code goes from a commit to production. Continuous Integration means developers merge small changes into the main branch frequently, and every change triggers an automated build and test run, so integration problems are found within minutes instead of at release time. Continuous Delivery extends this: every change that passes the pipeline is packaged and deployed automatically to test environments and is always ready to release to production, usually with an approval step. Continuous Deployment goes further and releases to production automatically. Tools include Jenkins, GitHub Actions, GitLab CI and Azure DevOps. The benefits are fast feedback, smaller and safer releases and repeatability.',
    'What metrics show that a CI/CD process is healthy?', sh),
  Q('nq-284', CI, 'E', 'concept', 'What is the difference between Continuous Integration and Continuous Delivery?',
    [kp('CI: build and test every change on merge', 'build', 'test', 'every change', 'merge'), kp('CD: deploy validated artifacts through environments, always releasable', 'releasable', 'environment*', 'deploy*'), kp('Continuous Deployment: automatic to production without manual approval', 'continuous deployment', 'without manual', 'automatic*'), kp('Delivery usually has a manual approval gate for production', 'manual approval', 'gate', 'approval')],
    'Continuous Integration is about the code: every commit or pull request is merged often and automatically built, unit tested and analysed, so the main branch always compiles and passes tests. Continuous Delivery is about releasing: the artifact produced by CI is automatically deployed through environments like dev, test and staging with further tests, so it is always in a releasable state, and going to production is a business decision, often a manual approval button. Continuous Deployment removes that manual step: every change that passes all stages goes to production automatically, which requires strong automated tests, monitoring and safe rollout strategies.',
    'What would you need in place before enabling continuous deployment?', { ...sh, sameAs: 'devops-001' }),
  Q('nq-285', CI, 'M', 'concept', 'What are the key stages of a CI/CD pipeline?',
    [kp('Checkout and build/compile', 'checkout', 'build', 'compile'), kp('Unit and integration tests, coverage', 'unit test*', 'integration test*', 'coverage'), kp('Static analysis and security scans (SonarQube, SAST, dependency, image scan)', 'sonarqube', 'static analysis', 'sast', 'dependency scan*', 'image scan*'), kp('Package and publish artifact/image to registry', 'package', 'artifact', 'image', 'registry'), kp('Deploy to environments with smoke tests, approvals, production rollout', 'deploy*', 'smoke test*', 'approval*', 'production')],
    'A typical pipeline: trigger on commit or pull request; check out the code; build and compile with Maven or Gradle; run unit tests and collect coverage with JaCoCo; static code analysis and quality gate with SonarQube; security scans, SAST, dependency vulnerability checks like OWASP Dependency-Check or Snyk, and secret scanning; package the artifact, a jar, then build a Docker image and scan it with Trivy; publish to an artifact repository or container registry with a version tag; deploy to dev and run integration and smoke tests; promote the same artifact to staging and QA, with performance tests; then a manual approval or automated gate and a production rollout with blue-green or canary, followed by monitoring and automatic rollback if health checks fail.',
    'Why should you build once and promote the same artifact?', sh),
  Q('nq-286', CI, 'E', 'scenario', 'What CI/CD tools have you used?',
    [kp('CI servers: Jenkins, GitHub Actions, GitLab CI, Azure DevOps', 'jenkins', 'github actions', 'gitlab', 'azure devops'), kp('Build/quality: Maven/Gradle, SonarQube', 'maven', 'gradle', 'sonarqube'), kp('Artifacts/registries: Nexus, Artifactory, ECR/ACR', 'nexus', 'artifactory', 'ecr', 'acr', 'docker hub'), kp('Deployment: Helm, Argo CD, Kubernetes, Terraform', 'helm', 'argo*', 'kubernetes', 'terraform'), kp('Describe your role in setting them up', 'set up', 'configured', 'wrote', 'pipeline*')],
    'Describe the toolchain you used and your role. For example: Jenkins with declarative Jenkinsfiles in each repository, later moving some services to GitHub Actions; Maven for builds and tests; SonarQube for quality gates; Snyk and Trivy for dependency and image scanning; Nexus for jars and Amazon ECR or Azure Container Registry for Docker images; Helm charts deployed to Kubernetes, with Argo CD doing GitOps for higher environments; and Terraform for infrastructure. Then explain what you personally did: wrote pipeline stages, added parallel test execution to cut build time, set up the quality gate, or fixed flaky deployments.',
    'What was the biggest improvement you made to a pipeline?', sh),
  Q('nq-287', CI, 'E', 'scenario', 'What happens after you commit and push code to GitHub?',
    [kp('Push to a feature branch; pull request opened', 'feature branch', 'pull request', 'pr'), kp('Webhook triggers CI pipeline: build, tests, scans', 'webhook', 'trigger*', 'pipeline'), kp('Status checks and code review gate the merge', 'status check*', 'code review', 'review', 'branch protection'), kp('Merge to main builds artifact/image and deploys to dev', 'merge', 'main', 'artifact', 'image', 'deploy*'), kp('Promotion to higher environments with approvals', 'promot*', 'staging', 'approval')],
    'In a typical setup I push to a feature branch and open a pull request. GitHub sends a webhook, or GitHub Actions starts directly, and the CI pipeline runs: build, unit and integration tests, SonarQube analysis and security scans. Results appear as status checks on the pull request, and branch protection requires them to pass plus a code review approval before merging. After merge into main, the pipeline builds the release artifact, a versioned jar and Docker image pushed to the registry, and deploys it automatically to the dev environment, running smoke tests. From there the same image is promoted to QA, staging and production, with approvals or automated gates, and monitoring after each deployment.',
    'How do you prevent broken code from reaching main?', sh),
  Q('nq-288', BT, 'E', 'concept', 'How does Maven build an application and resolve dependencies?',
    [kp('pom.xml declares coordinates, dependencies and plugins', 'pom.xml', 'pom', 'coordinates', 'groupid'), kp('Lifecycle phases: validate, compile, test, package, verify, install, deploy', 'lifecycle', 'compile', 'test', 'package', 'install'), kp('Dependencies downloaded from repositories into ~/.m2 local repository', '.m2', 'local repository', 'maven central', 'remote repositor*'), kp('Transitive dependencies, nearest-wins conflict resolution, dependencyManagement/BOM', 'transitive', 'nearest', 'dependencymanagement', 'bom'), kp('Scopes: compile, test, provided, runtime', 'scope*', 'provided', 'runtime')],
    'Maven reads the pom.xml, which defines the project coordinates, groupId, artifactId and version, its dependencies and plugins. Running a phase, like mvn package, executes all earlier phases of the default lifecycle in order, validate, compile, test, package, then verify, install to the local repository and deploy to a remote one, each phase running plugin goals such as compiler, surefire and jar. For dependencies, Maven first looks in the local repository in ~/.m2, otherwise downloads from configured remote repositories, Maven Central or a corporate Nexus, including transitive dependencies of your dependencies. Version conflicts are resolved by nearest definition wins, and you control versions with dependencyManagement or a BOM like Spring Boot. Scopes such as compile, test, provided and runtime decide where a dependency is available.',
    'How would you find and fix a dependency version conflict?', src),
  Q('nq-289', CI, 'M', 'scenario', 'How are automated tests integrated into a CI/CD pipeline?',
    [kp('Unit tests run on every commit/PR as a fast gate', 'every commit', 'pull request', 'fast', 'gate'), kp('Integration tests with Testcontainers in CI; parallelised', 'integration', 'testcontainers', 'parallel*'), kp('Test reports and coverage thresholds (JaCoCo, Sonar quality gate)', 'report*', 'coverage', 'jacoco', 'quality gate'), kp('Post-deploy smoke, API, E2E and performance tests in environments', 'smoke', 'e2e', 'end to end', 'performance', 'after deploy*'), kp('Failing tests stop the pipeline; handle flaky tests', 'fail*', 'stop', 'block*', 'flaky')],
    'Tests are stages that gate progress. On every pull request, the build runs unit tests, mvn test with Surefire, which must pass, and integration tests, mvn verify with Failsafe and Testcontainers. Results are published as JUnit reports, coverage is measured with JaCoCo and checked by the SonarQube quality gate, for example at least 80 percent on new code. After deploying to an environment, automated smoke tests and API tests run against the live service, and for staging, end-to-end and performance tests with JMeter or Gatling. Any failure stops promotion. To keep the pipeline fast, tests run in parallel, and flaky tests are tracked and fixed rather than ignored.',
    'How do you deal with flaky tests in CI?', sh),
  Q('nq-290', CI, 'M', 'concept', 'What is the role of SonarQube or similar code-quality tools?',
    [kp('Static analysis for bugs, code smells, vulnerabilities, security hotspots', 'static analysis', 'bug*', 'code smell*', 'vulnerabilit*', 'hotspot*'), kp('Measures coverage, duplication, complexity, technical debt', 'coverage', 'duplicat*', 'complexity', 'technical debt'), kp('Quality gate fails the pipeline on new issues', 'quality gate', 'fail*', 'new code'), kp('PR decoration and continuous inspection', 'pull request', 'decoration', 'continuous'), kp('Alternatives: Checkstyle, PMD, SpotBugs, Codacy', 'checkstyle', 'pmd', 'spotbugs')],
    'SonarQube performs continuous static analysis of the code in the pipeline. It detects bugs, such as possible null dereferences or resource leaks, code smells that hurt maintainability, security vulnerabilities and hotspots like SQL injection or weak crypto, and measures test coverage, using JaCoCo reports, duplication, complexity and estimated technical debt. Its quality gate defines thresholds, typically on new code: no new critical issues, coverage above 80 percent, duplication below a few percent, and if the gate fails, the pipeline fails. It also comments on pull requests. That keeps quality from eroding over time. Similar tools are Checkstyle, PMD and SpotBugs, and IDE plugins like SonarLint.',
    'Why is a quality gate on "new code" more practical than on the whole codebase?', sh),
  Q('nq-291', CI, 'M', 'concept', 'How do vulnerability and security scans fit into a deployment pipeline?',
    [kp('Shift left: scan early in PR builds', 'shift left', 'early', 'pull request'), kp('SAST on code, SCA dependency scanning (Snyk, OWASP Dependency-Check)', 'sast', 'sca', 'dependency', 'snyk', 'owasp'), kp('Secret scanning; container image scanning (Trivy) and IaC scanning', 'secret*', 'trivy', 'image scan*', 'iac', 'checkov'), kp('DAST against deployed environment', 'dast', 'zap', 'dynamic'), kp('Fail builds on critical/high severity with exceptions process; SBOM, signing', 'critical', 'high severity', 'fail', 'sbom', 'sign*')],
    'Security scanning is built into the pipeline, shifting left so issues are found early. On every pull request: secret scanning to stop credentials being committed; SAST, static application security testing of our code, via SonarQube or CodeQL; and software composition analysis of dependencies with Snyk, OWASP Dependency-Check or GitHub Dependabot to find known CVEs. When the Docker image is built, Trivy or Grype scans the OS packages and libraries, and Checkov or tfsec scan Terraform and Kubernetes manifests. After deployment to a test environment, DAST tools like OWASP ZAP probe the running API. The pipeline fails on critical or high findings, with a documented exception process, and we generate an SBOM and sign images.',
    'How do you handle a critical CVE found in a transitive dependency?', sh),
  Q('nq-292', BT, 'E', 'concept', 'What is the difference between a JAR and a WAR file?',
    [kp('JAR: Java archive of classes/resources; executable fat jar with embedded server', 'jar', 'executable', 'fat jar', 'embedded'), kp('WAR: web application archive deployed to an external servlet container', 'war', 'servlet container', 'tomcat', 'external'), kp('WAR structure: WEB-INF, web.xml, lib', 'web-inf', 'web.xml', 'lib'), kp('Spring Boot microservices usually use JARs', 'spring boot', 'microservice*', 'java -jar')],
    'A JAR, Java ARchive, is a zip file of compiled classes, resources and a manifest, used for libraries and for standalone applications; a Spring Boot executable fat jar also contains all dependencies and an embedded server, so you run it with java -jar. A WAR, Web application ARchive, packages a web application for deployment into an external servlet container or application server like Tomcat, JBoss or WebLogic, with a defined structure: WEB-INF with web.xml, WEB-INF/classes and WEB-INF/lib. Modern microservices and containers mostly use JARs, while WARs remain where organisations run shared application servers. Spring Boot can produce either.',
    'How do you make a Spring Boot app deployable as a WAR?', src),
  Q('nq-293', CI, 'E', 'concept', 'How do Jenkins pipelines work?',
    [kp('Pipeline as code in a Jenkinsfile stored in the repository', 'jenkinsfile', 'pipeline as code', 'repository'), kp('Declarative syntax: pipeline, agent, stages, steps, post', 'declarative', 'stages', 'steps', 'agent', 'post'), kp('Controller schedules jobs on agents/nodes', 'controller', 'master', 'agent*', 'node*'), kp('Triggered by webhooks, schedules or manually; multibranch', 'webhook', 'trigger*', 'multibranch'), kp('Plugins, credentials, shared libraries', 'plugin*', 'credential*', 'shared librar*')],
    'A Jenkins pipeline defines the build, test and deploy process as code in a Jenkinsfile kept in the repository, so it is versioned and reviewed like any code. The declarative syntax has a pipeline block with an agent saying where to run, often a Docker or Kubernetes pod agent, environment variables, stages such as Build, Test, Scan and Deploy each containing steps, and a post section for actions on success, failure or always, like publishing test reports or notifying Slack. The Jenkins controller schedules the run on agents. Pipelines are triggered by webhooks from GitHub, polling, schedules or manually; multibranch pipelines create a job per branch and pull request. Credentials come from the Jenkins credentials store, and shared libraries reuse common logic across teams.',
    'What is the difference between declarative and scripted pipelines?', sh),
  Q('nq-294', CI, 'M', 'concept', 'What is a Jenkins pipeline script written in Groovy?',
    [kp('Jenkinsfile uses a Groovy-based DSL', 'groovy', 'dsl'), kp('Scripted pipeline: node { stage { } } full Groovy flexibility', 'scripted', 'node', 'flexib*'), kp('Declarative pipeline: structured, simpler, validated', 'declarative', 'structured'), kp('script {} blocks and shared libraries for custom logic', 'script block', 'script {', 'shared librar*'), kp('Sandbox/script approval for security', 'sandbox', 'script approval', 'security')],
    'Jenkinsfiles are written in a domain-specific language based on Groovy. There are two flavours. Scripted pipelines, starting with node { stage(\'Build\') { sh \'mvn package\' } }, are plain Groovy code with loops, conditions and functions, very flexible but harder to read and maintain. Declarative pipelines, starting with pipeline { agent any; stages { ... } }, have a fixed structure that Jenkins validates, easier for most teams, with script { } blocks when you need Groovy logic. Complex reusable logic goes into shared libraries written in Groovy under vars and src. For security, Groovy runs in a sandbox, and non-whitelisted methods need administrator script approval.',
    'How would you share pipeline code across 50 repositories?', sh),
  Q('nq-295', CI, 'E', 'concept', 'What is a webhook, and how does it trigger a pipeline?',
    [kp('HTTP callback sent by a system when an event happens', 'http callback', 'http post', 'event'), kp('Git provider sends push/PR event payload to CI server URL', 'push', 'pull request', 'payload', 'github'), kp('CI server matches repo/branch and starts the job', 'start*', 'trigger*', 'job', 'branch'), kp('Secured with secret/signature; avoids polling', 'secret', 'signature', 'hmac', 'polling')],
    'A webhook is an HTTP callback: when an event happens in one system, it sends an HTTP POST with a JSON payload to a URL registered by another system. In CI/CD, you configure a webhook in GitHub, GitLab or Bitbucket pointing to the Jenkins or other CI server endpoint. When someone pushes a commit or opens a pull request, the git provider immediately posts the event, including repository, branch and commit, and the CI server matches it to the right job and starts the pipeline. This is faster and cheaper than polling the repository. Webhooks should be secured with a shared secret so the CI server can verify the HMAC signature.',
    'What would you check if pushes stopped triggering builds?', sh),
  Q('nq-296', CI, 'M', 'scenario', 'How do you define build stages and deployment steps in a pipeline?',
    [kp('Stages in order: build, test, analyse, package, publish, deploy', 'stages', 'build', 'test', 'deploy'), kp('Steps run commands (mvn, docker build/push, helm/kubectl)', 'mvn', 'docker build', 'helm', 'kubectl'), kp('Conditions: branch-based (when), parallel stages, approvals (input)', 'when', 'branch', 'parallel', 'input', 'approval'), kp('Environment-specific config and credentials', 'credential*', 'environment', 'secret*'), kp('Post actions: reports, notifications, rollback', 'post', 'notif*', 'rollback', 'report*')],
    'In a declarative Jenkinsfile, or a GitHub Actions workflow, I define ordered stages, each with steps. Build runs mvn -B clean package; Test runs unit and integration tests, maybe in parallel stages; Quality runs the SonarQube scan and waits for the quality gate; Package builds the Docker image tagged with the commit SHA and version; Publish pushes it to the registry using stored credentials; then Deploy stages per environment run helm upgrade --install with environment-specific values, or update a GitOps repository. when conditions restrict deployment stages to the main branch, an input step or environment protection rule adds manual approval for production, and post sections publish test reports, notify the team and trigger rollback on failure.',
    'Can you show what a minimal declarative Jenkinsfile for a Spring Boot service looks like?', sh),
  Q('nq-297', CI, 'M', 'scenario', 'How do you push an application image or artifact to a registry?',
    [kp('Build image with docker build / Jib / buildpacks', 'docker build', 'jib', 'buildpack*'), kp('Tag with version/commit SHA, avoid relying on latest', 'tag', 'sha', 'version', 'latest'), kp('Authenticate (docker login / cloud credentials) and docker push', 'docker login', 'docker push', 'authenticat*', 'credential*'), kp('Registries: ECR, ACR, GCR, Docker Hub, Nexus/Artifactory; mvn deploy for jars', 'ecr', 'acr', 'docker hub', 'nexus', 'artifactory', 'mvn deploy'), kp('Scan and sign images; immutable tags', 'scan*', 'sign*', 'immutable')],
    'For a container image, the pipeline builds it with docker build, or Jib or Cloud Native Buildpacks for Spring Boot without a Dockerfile, and tags it uniquely, for example registry/orders-service:1.4.2 and the git commit SHA, rather than relying on latest. It authenticates to the registry with credentials from the CI secret store: docker login, aws ecr get-login-password for Amazon ECR, or az acr login for Azure, then runs docker push. For jar artifacts, mvn deploy publishes to Nexus or Artifactory based on distributionManagement. Good practice adds an image vulnerability scan before or after pushing, image signing with cosign, and immutable tags so a version can never be overwritten.',
    'Why is deploying the "latest" tag risky?', sh),
  Q('nq-298', CI, 'M', 'scenario', 'How is an application deployed to development, staging, and production environments?',
    [kp('Build once, promote the same artifact across environments', 'build once', 'same artifact', 'promot*'), kp('Environment-specific config via profiles, Helm values, config server, secrets', 'profile*', 'helm values', 'config*', 'secret*'), kp('Automatic to dev, gated to staging/production (approvals, tests)', 'automatic*', 'approval*', 'gate*'), kp('Deployment strategies: rolling, blue-green, canary', 'rolling', 'blue green', 'blue-green', 'canary'), kp('Smoke tests, monitoring and rollback', 'smoke test*', 'monitor*', 'rollback')],
    'We build the artifact once and promote that same image through environments, so what was tested is what goes live. Differences between environments live outside the image: Spring profiles, Helm values files per environment, a config server, and secrets from Vault or a cloud secret manager. Deployment to dev happens automatically after merge; promotion to QA and staging happens after automated tests pass, and to production after a manual approval or change ticket, often at a defined window. In Kubernetes, Helm or Argo CD apply the change using rolling updates, or blue-green and canary for risky changes. Each deployment is followed by smoke tests and monitoring of error rates and latency, with automated or one-click rollback.',
    'How do you handle database schema changes during deployment?', sh),
  Q('nq-299', CI, 'M', 'concept', 'Why might automated deployment be restricted in higher environments?',
    [kp('Risk to customers and revenue; production stability', 'risk', 'customer*', 'stability', 'production'), kp('Compliance/audit/change management (SOX, ITIL, CAB)', 'compliance', 'audit', 'change management', 'cab', 'regulat*'), kp('Segregation of duties and access control', 'segregation of duties', 'separation of duties', 'access'), kp('Release windows, coordination with business and dependent teams', 'release window*', 'coordinat*', 'business'), kp('Approvals/gates rather than fully manual steps', 'approval*', 'gate*', 'manual')],
    'In production and pre-production a bad deployment directly affects customers, revenue and data, so organisations add controls. Regulated industries need audit trails and change management, such as a CAB approval or SOX controls, and segregation of duties: the developer who wrote the code should not alone push it to production. There may be release windows to avoid peak hours, coordination with other teams, database migrations, or business sign-off after UAT. So the pipeline is still automated, but promotion to production is gated by approvals, change tickets and checks rather than triggered on every merge; mature teams reduce friction with automated evidence and progressive delivery.',
    'How can you keep the speed of automation while meeting audit requirements?', sh),
  Q('nq-300', CI, 'SL', 'concept', 'What are deployment guardrails, and why are they important?',
    [kp('Automated safety checks that prevent bad or unsafe deployments', 'automated', 'safety', 'prevent', 'check*'), kp('Quality/security gates, policy as code (OPA, Kyverno)', 'quality gate', 'security gate', 'policy as code', 'opa', 'kyverno'), kp('Progressive delivery: canary analysis, health checks, automatic rollback', 'canary', 'health check*', 'automatic rollback', 'progressive'), kp('Limits: approvals, deployment windows, resource limits, required probes', 'approval*', 'window*', 'resource limit*', 'probe*'), kp('Reduce blast radius while keeping speed', 'blast radius', 'speed')],
    'Guardrails are automated controls that keep deployments safe without blocking teams with manual work. Examples: the pipeline refuses to deploy if tests, the SonarQube quality gate or vulnerability scans fail; policy-as-code with OPA Gatekeeper or Kyverno rejects Kubernetes manifests without resource limits, health probes or with privileged containers or unapproved registries; only signed images can run; production deploys require an approval and are blocked during freeze windows; and progressive delivery with Argo Rollouts or Flagger shifts a small percentage of traffic, checks error rates and latency, and automatically rolls back if SLOs are breached. They matter because they reduce the blast radius of mistakes and let teams deploy frequently with confidence.',
    'Which guardrail would you add first in a team that deploys manually today?', sh),
  Q('nq-301', CI, 'M', 'concept', 'What is the role of an SRE team in deployment?',
    [kp('Owns reliability: SLOs, error budgets, monitoring and alerting', 'slo*', 'error budget*', 'monitor*', 'alert*'), kp('Builds deployment platforms, automation and safe rollout practices', 'platform', 'automation', 'rollout', 'canary'), kp('Production readiness reviews, capacity planning', 'readiness review', 'capacity', 'production readiness'), kp('On-call, incident response, postmortems, rollback', 'on call', 'on-call', 'incident*', 'postmortem*', 'rollback'), kp('Error budget policy may slow or freeze releases', 'freeze', 'slow down', 'policy')],
    'Site Reliability Engineering applies software engineering to operations. In deployments the SRE team usually owns or co-owns the reliability side: they define SLOs and error budgets with product teams, build and maintain the deployment platform, observability and alerting, and promote safe practices such as canary releases, feature flags, automatic rollback and runbooks. They run production readiness reviews before a new service goes live, plan capacity, take part in on-call, lead incident response and blameless postmortems. With an error budget policy, if a service has used up its budget, releases may be slowed or frozen until reliability improves. In you build it, you run it organisations, SREs enable the product teams rather than deploy for them.',
    'What is an error budget and how does it influence release decisions?', sh),
];
